    chefName: "François-Régis Gaudry",
    time: "40min",
    serves: "4 pers.",
    difficulty: "Moyen",
    image: "https://instagram.fctt1-1.fna.fbcdn.net/v/t51.82787-15/681928974_18591538720028753_3889091277223172781_n.jpg?stp=dst-jpg_e15_p480x480_tt6&_nc_cat=108&ig_cache_key=Mzg4NDM0MzQ2MTU0NTU0MDI4Mg%3D%3D.3-ccb7-5&ccb=7-5&_nc_sid=58cdad&efg=eyJ2ZW5jb2RlX3RhZyI6IkNBUk9VU0VMX0lURU0ueHBpZHMuNTc2LnNkci52aWRlb19kZWZhdWx0X2NvdmVyX2ZyYW1lLkMzIn0%3D&_nc_ohc=6XZXuqBmvYAQ7kNvwEFOCoL&_nc_oc=Adr54gPPN304SYksB_Nh9dFSqV7vLfhUBVX79j28NUMQps9EdAClRThqrqFne6UPG6IEbB0SXSLnDjexsveEnzxK&_nc_ad=z-m&_nc_cid=0&_nc_zt=23&_nc_ht=instagram.fctt1-1.fna&_nc_gid=wdb2JqneJTn9BDnOVvYXNQ&_nc_ss=7a22e&oh=00_AQImDNxZpmdNJ9ts7YDfM6XGDvsb5dx-2dOQ9RUjt8-OOQ&oe=6AADAFD0\n🔥LE MEILLEUR DE MA SEMAINE🔥\n\nAvec ma bande de @ttbontv, on était en vadrouille à Arles cette semaine pour une spéciale Camargue ! ➡️ Bientôt sur @parispremiere 📺\n\n2 et 3) Le tournage a démarré fort autour d’une asperge blanche à la texture merveilleuse chez @inari.arles, la table de @celine_pham_ et sa bande\n4) Les cookies de @mazettearles, coffee shop engagé et enjoué\n5) Riche sélection de vins naturels chez @cavebienvivantarles\n6 et 7) Les assiettes ensoleillées et partageuses de @paourestaurant\n8) À la recherche de l’artichaut de Provence aux @jardinsdecidamos\n9 à 11) La bistronomie à l’arlésienne et les vins vivants chez @mesa_arles\n12) Le tea time grandiose de @yohan.soriano, nouveau chef pâtissier de @larlatan\n13 et 14) Les tacos à l’effilochée de guardiane de Toro de Gastón @taqueriaelluchon \n15 à 18) Tournage à la @chassagnette avec @armsfeelgood et ses assiettes printanières @nathandoumaux. Et tout ça le jour de l’annniversaire de Mina !\n19) c’est de l’amour… @antonycointre\n20) À très très vite dans Très Très Bon spécial Camargue ! @minasndrm @valentine.oud @antonycointre \n\n#arles #camargue",
