    image: "https://instagram.fctt1-1.fna.fbcdn.net/v/t51.82787-15/675436969_18582946564002167_6231589297083996185_n.jpg?stp=dst-jpg_e15_p480x480_tt6&_nc_cat=102&ig_cache_key=Mzg4MjM0ODIxNDA3MDM0NDcyOQ%3D%3D.3-ccb7-5&ccb=7-5&_nc_sid=58cdad&efg=eyJ2ZW5jb2RlX3RhZyI6IkNBUk9VU0VMX0lURU0ueHBpZHMuNzIwLnNkci52aWRlb19kZWZhdWx0X2NvdmVyX2ZyYW1lLkMzIn0%3D&_nc_ohc=NB2RVOdL8h4Q7kNvwEF2ef8&_nc_oc=AdpDeAoS49t4IQkWbCgkndH397xfhTNmNpI8NU0Z_q3ZBTKVSw-w1sT_g4ce4GDpcfUsM_2KhqltbxT_Gks19cOn&_nc_ad=z-m&_nc_cid=0&_nc_zt=23&_nc_ht=instagram.fctt1-1.fna&_nc_gid=WBNsYAXCyScioIct_-KQUA&_nc_ss=7a22e&oh=00_AQJybWHt46pJkvEyL2G0ZqrHC2FPIeLdK0pBN_Y-XN3TEw&oe=6AADB3E0\nMy favourite kind of cooking at the moment: one pan, into the oven - not much to do but wait.\n\nThis week’s recipes are exactly that. Two mezze-style dishes for the middle of the table: soft saffron courgettes with tzatziki, and smoky aubergines with olives and tomatoes - collapsed, jammy, and best at room temperature with bread alongside. (The Greeks call that last part papara - a more poetic way of saying you’ll want a whole loaf.) The aubergines improve overnight, so make them the day before if you can.\n\nBoth recipes in this week’s Substack - find them via the link in bio.",
